function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function post(path, body) {
  const response = await fetch(apiOrigin() + path, {
    method: 'POST',
    headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  return response.json()
}

async function run(input) {
  const hasYaml = typeof input.yaml === 'string' && input.yaml.trim().length > 0
  const hasConfig = input.config && typeof input.config === 'object' && !Array.isArray(input.config)
  if (hasYaml === Boolean(hasConfig)) throw new Error('Provide exactly one of yaml or config')
  const representation = hasYaml ? { yaml: input.yaml } : { config: input.config }
  if (input.python_source !== undefined) representation.python_source = String(input.python_source)
  const validation = await post('/api/strategies/validate', representation)
  if (input.operation === 'validate') return validation
  if (!validation.valid) throw new Error('Strategy validation failed')
  const implementation = validation.config?.implementation?.kind || 'configured'
  if (implementation === 'python' && input.confirm_python_execution !== true) {
    throw new Error('Python strategy research requires an explicit user request and confirm_python_execution=true')
  }
  const body = { yaml: validation.normalized_yaml, profile: input.profile === 'runtime' ? 'runtime' : 'demo' }
  if (input.python_source !== undefined) body.python_source = String(input.python_source)
  if (input.operation === 'selection_preview') {
    if (validation.strategy_type !== 'stock_selection') throw new Error('selection_preview requires a stock_selection strategy')
    if (input.as_of_date) body.as_of_date = String(input.as_of_date)
    return post('/api/strategies/selection-preview', body)
  }
  if (input.operation === 'timing_research') {
    if (validation.strategy_type !== 'market_timing') throw new Error('timing_research requires a market_timing strategy')
    if (!input.start_date || !input.end_date) throw new Error('start_date and end_date are required for timing_research')
    body.start_date = String(input.start_date)
    body.end_date = String(input.end_date)
    return post('/api/strategies/timing-research', body)
  }
  throw new Error('Unsupported strategy research operation')
}
